var TGAT1_QA_KB=[{keys:["present simple","present tense","ปัจจุบัน","present"],type:"grammar",q:"What is Present Simple tense?",a:"Present Simple describes habits, routines, facts, and permanent situations. Use it for things that happen regularly or are always true. Structure: subject + base verb (I/you/we/they) or subject + verb-s (he/she/it).",ex:["I go to school every day.","She likes coffee.","Water boils at 100C."],err:"Forgetting -s on third person singular (he go -> he goes)"},{keys:["present continuous","present progressive","be + ing","กำลัง"],type:"grammar",q:"What is Present Continuous?",a:"Present Continuous describes an action happening right now or around the present moment. Structure: subject + be (am/is/are) + verb-ing. Also used for future arrangements.",ex:["I am studying now.","She is working on a project.","We are meeting tomorrow at 5 PM."],err:"Using -ing without be verb, or using it for habits"},{keys:["past simple","past tense","อดีต"],type:"grammar",q:"What is Past Simple tense?",a:"Past Simple describes completed actions in the past. Use -ed for regular verbs, irregular forms for irregular verbs. Structure: subject + V2.",ex:["I visited Bangkok last year.","She went home early.","They studied English at school."],err:"Using base form instead of V2"},{keys:["past continuous","was were ing"],type:"grammar",q:"What is Past Continuous?",a:"Past Continuous describes an action in progress at a specific time in the past. Structure: subject + was/were + verb-ing. Often used with Past Simple to show interruption.",ex:["I was reading when the phone rang.","They were playing football when it rained.","She was cooking dinner at 6 PM."],err:"Using was/were with wrong subject"},{keys:["present perfect","have has","perfect"],type:"grammar",q:"What is Present Perfect tense?",a:"Present Perfect connects past actions to the present. Use have/has + V3. Use it for: experiences, recent past with present result, unspecified time, continuing actions.",ex:["I have visited Japan three times.","She has finished her homework.","I have lived here since 2020."],err:"Confusing with Past Simple (use Past Simple with specific past time)"},{keys:["past perfect","had","v3"],type:"grammar",q:"What is Past Perfect tense?",a:"Past Perfect describes an action completed before another past action. Structure: subject + had + V3. It sets the earlier action in a sequence of past events.",ex:["I had finished my work before he arrived.","She had left before I got there.","They had already eaten when I arrived."],err:"Using with simple past without a clear earlier action"},{keys:["future","will","going to","อนาคต"],type:"grammar",q:"Will vs Be Going To?",a:"Use will for: spontaneous decisions, predictions, promises. Use be going to for: planned intentions, predictions based on evidence. Both describe future actions.",ex:["I will help you. (spontaneous)","I am going to study medicine. (planned)","Look at those clouds! It is going to rain. (evidence)"],err:"Using going to for spontaneous decisions"},{keys:["conditional","if","type 0","type 1","type 2","type 3"],type:"grammar",q:"What are the types of conditionals?",a:"Type 0: Zero Conditional - general truths (If + present, present). Type 1: First Conditional - real future possibilities (If + present, will). Type 2: Second Conditional - unreal/hypothetical present (If + past, would). Type 3: Third Conditional - unreal past (If + past perfect, would have V3).",ex:["If you heat ice, it melts. (Type 0)","If it rains, I will stay home. (Type 1)","If I were rich, I would travel. (Type 2)","If I had studied harder, I would have passed. (Type 3)"],err:"Mixing conditional types"},{keys:["passive","被动","passive voice"],type:"grammar",q:"What is Passive Voice?",a:"Passive voice emphasizes the action or receiver rather than the doer. Structure: be + V3. Use it when the doer is unknown, unimportant, or the receiver is the focus.",ex:["The letter was written by Tom.","English is spoken worldwide.","The meeting will be held tomorrow."],err:"Forgetting be verb or using wrong V form"},{keys:["modal","can","could","should","must","may","might"],type:"grammar",q:"What are modal verbs?",a:"Modal verbs express ability, permission, obligation, possibility, or advice. can/could = ability/permission, may/might = possibility, must = obligation, should = advice, would = polite request/hypothetical. Modals are always followed by base verb.",ex:["I can speak English. (ability)","You should study more. (advice)","He must finish this today. (obligation)","It might rain tomorrow. (possibility)"],err:"Using modal + -ing or modal + V3"},{keys:["gerund","infinitives","to verb","v-ing"],type:"grammar",q:"Gerunds vs Infinitives?",a:"Gerunds (V-ing) and infinitives (to V) both function as nouns. Use gerunds after prepositions and after verbs like enjoy, avoid, finish. Use infinitives after want, decide, hope, promise, and after adjectives.",ex:["I enjoy reading. (gerund)","I want to go home. (infinitive)","She avoids talking to strangers. (gerund)","I hope to see you soon. (infinitive)"],err:"Using wrong form after specific verbs"},{keys:["reported speech","indirect speech","reported","say told"],type:"grammar",q:"What is Reported Speech?",a:"Reported speech is when you tell someone what another person said, without quoting directly. Shift tense: Present to Past, Will to Would, Can to Could. Change time adverbs: now to then, tomorrow to the next day. Questions become if/whether or wh-words.",ex:["Direct: I am tired, she said. Reported: She said that she was tired.","Direct: I will call you, he said. Reported: He said that he would call me.","Direct: Can you help? she asked. Reported: She asked if I could help."],err:"Forgetting to shift tense or change pronouns"},{keys:["relative clause","relative pronoun","who which where","that"],type:"grammar",q:"What are Relative Clauses?",a:"Relative clauses give extra information about a noun, introduced by relative pronouns: who (person), which (thing), where (place), whose (possession), that (thing/person). They define or identify the noun.",ex:["The man who lives next door is a doctor.","The book which I bought is interesting.","This is the city where I was born.","The girl whose bag is red is my sister."],err:"Omitting the relative pronoun incorrectly or using wrong pronoun"},{keys:["subject verb agreement","sva","agreement","agrees"],type:"grammar",q:"What is Subject-Verb Agreement?",a:"The verb must match the subject in number. Singular subjects take singular verbs, plural take plural. With each, every, any + singular noun -> singular verb. With compound subjects joined by and -> plural verb.",ex:["She goes to school. (singular)","They go to school. (plural)","Each student has a book. (singular)","Both Tom and Jerry are here. (plural)"],err:"Ignoring intervening phrases"},{keys:["idiom","สำนวน","idioms"],type:"vocab",q:"What are idioms?",a:"Idioms are expressions whose meaning cannot be understood from the individual words. The whole phrase has a figurative meaning. Learning idioms helps with natural communication and TGAT1 reading/listening comprehension.",ex:["It is raining cats and dogs. (raining heavily)","Break a leg! (good luck)","I am under the weather. (sick)","Once in a blue moon. (rarely)"],err:"Translating idioms literally"},{keys:["synonym","คำใกล้","ความหมายใกล้"],type:"vocab",q:"What are synonyms?",a:"Synonyms are words with the same or very similar meanings. Learning synonyms helps with reading comprehension and vocabulary expansion. However, synonyms are rarely 100% identical - nuance and context matter.",ex:["important = significant, crucial, essential","big = large, huge, enormous","happy = glad, joyful, delighted, pleased"],err:"Using synonyms without checking context"},{keys:["antonym","คำตรงข้าม","ความหมายตรงข้าม"],type:"vocab",q:"What are antonyms?",a:"Antonyms are words with opposite meanings. Recognizing antonyms helps with reading comprehension, especially when authors use contrast to convey meaning.",ex:["increase = decrease","important = unimportant","happy = sad, unhappy","old = new"],err:"Confusing near-opposites with true antonyms"},{keys:["phrasal verbs","phrasal","verb + preposition"],type:"vocab",q:"What are phrasal verbs?",a:"Phrasal verbs are a verb combined with a preposition or adverb that creates a meaning different from the individual words. They are very common in spoken English and TGAT1 exams. Learn them as single units with their meanings.",ex:["give up = stop doing something","put off = postpone","look forward to = excited about future","run out of = use all of something"],err:"Treating phrasal verbs as separate words"},{keys:["collocation","collocations","word pair"],type:"vocab",q:"What are collocations?",a:"Collocations are words that naturally go together. English has strong word-pair preferences that do not follow logic. Learning common collocations helps you sound natural and answer cloze questions correctly.",ex:["make a decision (not do a decision)","take a risk (not make a risk)","heavy rain (not big rain)","fast food (not quick food)"],err:"Using logical but non-native word combinations"},{keys:["preposition","บุพบท","at on in"],type:"grammar",q:"When to use prepositions at/on/in?",a:"Use at for specific points (at 5 PM, at school, at the corner). Use on for surfaces and days (on Monday, on the table, on the bus). Use in for enclosed spaces and longer periods (in the room, in July, in 2024).",ex:["at 6 o clock, at home, at the station","on the table, on Friday, on the phone","in the box, in June, in Thailand"],err:"Mixing prepositions for time and place"},{keys:["article","a an the"],type:"grammar",q:"When to use a/an/the?",a:"Use a/an for non-specific singular countable nouns (a book, an apple). Use the when the noun is specific or already mentioned. No article for plural/uncountable non-specific nouns.",ex:["I saw a dog. (any dog)","I saw the dog. (specific dog)","Dogs are friendly. (plural, no article)"],err:"Using a/an with uncountable nouns"},{keys:["comparative","superlative","comparison","เปรียบเทียบ"],type:"grammar",q:"Comparative vs Superlative?",a:"Comparative compares two things: adjective + -er or more + adjective. Superlative compares three or more: adjective + -est or most + adjective. Use the before superlatives.",ex:["She is taller than me. (comparative)","She is the tallest in the class. (superlative)","This book is more interesting than that one."],err:"Using comparative with 3+ items or superlative with 2 items"},{keys:["conjunction","connector","คำเชื่อม","but and so"],type:"grammar",q:"What are conjunctions and connectors?",a:"Conjunctions join words, phrases, or clauses. Coordinating: and, but, or, so, nor. Subordinating: because, when, if, although, while, unless. Transition words connect ideas between sentences: however, therefore, moreover, nevertheless.",ex:["I like tea but she likes coffee. (contrast)","I stayed home because I was tired. (reason)","However, the result was positive. (transition)"],err:"Using connectors without proper clause structure"},{keys:["cloze","text completion","เติมคำ"],type:"strategy",q:"How to approach Text Completion (cloze) questions?",a:"1. Read the whole sentence/passage first. 2. Determine what part of speech the blank needs (noun, verb, adj, adv). 3. Look at surrounding context for clues. 4. Eliminate options that do not fit grammatically. 5. Check meaning fits.",ex:["The ____ of the project took two years. -> noun needed -> development","She answered ____. -> adverb needed -> clearly"],err:"Filling the blank without checking grammar or context"},{keys:["reading comprehension","reading","จับใจความ","อ่าน"],type:"strategy",q:"How to approach Reading Comprehension?",a:"1. Read the questions first to know what to look for. 2. Skim the passage for the main idea. 3. Locate evidence for each question in the text. 4. Choose answers that are supported by evidence, not assumptions. 5. Watch for paraphrasing - correct answers often restate the text.",ex:["Q: Why did she leave? Find because or reason words in passage","Q: What can be inferred? Find clues, not direct statements"],err:"Choosing answers that are true in general but not supported by the passage"},{keys:["question response","q&r","คำถามตอบ","question-response"],type:"strategy",q:"How to approach Question-Response questions?",a:"1. Read the question and predict what type of answer is needed (yes/no, opinion, reason, time, etc.). 2. Think of a natural response before looking at options. 3. Match your predicted response type to the options. 4. Eliminate options that do not match the question type.",ex:["Q: How often do you exercise? Answer with frequency: Every day.","Q: Would you like some tea? Answer: Yes, please. or No, thanks."],err:"Choosing answers that do not match the question type"},{keys:["conversation","conversation short long","บทสนทนา"],type:"strategy",q:"How to approach conversation questions?",a:"1. Read the full dialogue to understand the situation. 2. Identify who is speaking and the relationship. 3. Look at the sentence before and after the blank. 4. Choose the most natural, contextually appropriate response. 5. Check tone (formal/informal).",ex:["A: How are you? B: I am fine, thanks.","A: Could you help me? B: Sure, what do you need?"],err:"Choosing responses that are grammatically correct but contextually wrong"},{keys:["error","mistake","wrong","ผิด","ข้อผิด"],type:"strategy",q:"How to learn from mistakes?",a:"Mistakes are part of learning - every error is a chance to strengthen understanding. The hub tracks your error patterns and brings similar concepts back in later review sessions. Do not get discouraged; each revisit builds confidence and reinforces the correct pattern.",ex:["Wrong: I have went to school. Correct: I have gone to school.","Wrong: She does not like coffee. Correct: She does not like coffee."],err:"Ignoring mistakes or feeling discouraged - the loop-back system is designed for this"}];
function TGAT1_QA_match(t){
t=String(t||"").toLowerCase().trim();
if(!t)return null;
for(const e of TGAT1_QA_KB){for(const k of e.keys){if(t.includes(k))return e;}}
const words=t.split(/[\s,.?]+/);
let best=null,bestScore=0;
for(const e of TGAT1_QA_KB){let score=0;for(const k of e.keys){if(words.some(w=>w.includes(k)||k.includes(w)))score+=2;}if(score>bestScore){bestScore=score;best=e;}}
return bestScore>=2?best:null;
}

